@MainActor
func testCancelledGitHubCLIProbePublishesNothing() async {
  let store = AppStore()
  let runner = GatedGHRunner()
  store.statusResolver = WorkroomStatusResolver(runner: runner)
  store.githubCLIStatus = .available

  let resolver = store.statusResolver
  let task = Task { await store.refreshGitHubCLI(resolver: resolver) }
  // Cancel only once the probe is genuinely in flight, or the guard under test never runs.
  let deadline = Date().addingTimeInterval(2)
  while !runner.enteredGHProbe && Date() < deadline {
    try? await Task.sleep(nanoseconds: 2_000_000)
  }
  XCTAssertTrue(runner.enteredGHProbe, "the gh auth probe never started")
  task.cancel()
  // Release the probe only AFTER cancelling — this is what proves `task.value` blocks on the
  // runner's own decision (single-flight ignores cancellation) rather than on any timer.
  runner.release()

  // Safety net, not the mechanism under test: if a future change to `GatedGHRunner` ever leaves
  // the continuation unresumed, fail fast with a clear message instead of hanging the whole run.
  let returnedInTime = await withTaskGroup(of: Bool.self) { group in
    group.addTask { await task.value; return true }
    group.addTask {
      try? await Task.sleep(nanoseconds: 5_000_000_000)
      return false
    }
    let first = await group.next() ?? false
    group.cancelAll()
    return first
  }
  XCTAssertTrue(returnedInTime, "refreshGitHubCLI did not return within 5s of the probe being released")

  XCTAssertEqual(store.githubCLIStatus, .available, "a cancelled probe published a verdict")
}

