import AppKit
import XCTest

/// Shared "let the SwiftUI/AppKit run loop catch up" waiter for the WORKROOM-2B/2T/2S app-hang
/// regression suites (`ChangedFileRowInvalidationTests`, `HistoryRowInvalidationTests`,
/// `DiffViewerLazyRenderingTests`, `AgentResumeCoordinatorTests`).
///
/// Pumps the run loop in short slices, forcing layout each time, until either `condition` returns
/// true or `seconds` elapses — whichever comes first. `condition` defaults to `{ false }`, which
/// makes this behave exactly like the old per-file busy-wait (always burns the full `seconds`):
/// some call sites are waiting out an unrelated async race (e.g. a status probe) rather than a
/// render they can observe, and forcing a fabricated condition onto those would be worse than no
/// condition at all. Pass a real condition wherever one exists (e.g. a `bodyPasses` counter tied
/// to the assertion that follows) to return as soon as the work is actually done instead of always
/// paying the ceiling.
extension XCTestCase {
  @MainActor
  func settle(_ view: NSView, seconds: TimeInterval = 0.6, until condition: () -> Bool = { false }) {
    let deadline = Date().addingTimeInterval(seconds)
    while Date() < deadline {
      view.layoutSubtreeIfNeeded()
      RunLoop.current.run(until: Date().addingTimeInterval(0.02))
      if condition() { break }
    }
    view.layoutSubtreeIfNeeded()
  }
}

import AppKit
import XCTest

@testable import Workroom

/// Direct coverage for the shared `settle(_:seconds:until:)` helper itself (see `Settle.swift`) —
/// this is new shared infrastructure whose blast radius is 4 call sites at once, so its own
/// early-exit and ceiling-enforcement contracts get a dedicated test rather than being inferred
/// only from the 4 rewritten call sites.
final class SettleTests: XCTestCase {

  @MainActor
  func testReturnsEarlyOnceConditionIsTrue() {
    let view = NSView()
    let start = Date()
    var checks = 0
    settle(
      view, seconds: 2,
      until: {
        checks += 1
        return checks >= 3
      })
    let elapsed = Date().timeIntervalSince(start)
    XCTAssertLessThan(
      elapsed, 1.0, "should return well before the 2s ceiling once the condition flips true")
  }

  @MainActor
  func testRespectsTheCeilingWhenConditionNeverBecomesTrue() {
    let view = NSView()
    let start = Date()
    settle(view, seconds: 0.3, until: { false })
    let elapsed = Date().timeIntervalSince(start)
    XCTAssertGreaterThanOrEqual(elapsed, 0.3, "must not return before the ceiling")
    XCTAssertLessThan(elapsed, 1.5, "must not hang well past the ceiling either")
  }

  @MainActor
  func testDefaultConditionBehavesLikeTheOldUnconditionalBusyWait() {
    let view = NSView()
    let start = Date()
    settle(view, seconds: 0.3)
    let elapsed = Date().timeIntervalSince(start)
    XCTAssertGreaterThanOrEqual(
      elapsed, 0.3, "omitting `until` must burn the full ceiling, matching every pre-existing "
        + "call site that has no observable convergence signal")
  }
}

